test("builds the hand-run command", () => {
	assert.equal(forkCommand(SOURCE, SESSION, ""), `pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here"`);
	assert.equal(
		forkCommand(SOURCE, SESSION, "foo"),
		`pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here foo"`,
	);
	assert.equal(
		forkCommand(SOURCE, SESSION, 'say "hi"'),
		`pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here say \\"hi\\""`,
	);
});

test("notice names the fork and points at the dashboard when registered", () => {
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: true }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · dashboard floating`,
	);
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: true, projectName: "scripts", pane: 3 }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · dashboard scripts #3`,
	);
	assert.equal(
		buildNotice({
			sessionId: SESSION,
			sourceSession: SOURCE,
			args: "foo",
			registered: true,
			resume: "pi --session 5b1c",
		}),
		`learn → fork ${SESSION} · pi --session 5b1c · dashboard floating`,
	);
});

test("a refused registration says why", () => {
	assert.match(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "", registered: false, refused: "Not here." }),
		/ · dashboard refused: Not here\.$/,
	);
});

test("notice carries the command when the dashboard did not register the fork", () => {
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "foo", registered: false }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · run: pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here foo"`,
	);
	assert.equal(
		buildNotice({ sessionId: SESSION, sourceSession: SOURCE, args: "", registered: false }),
		`learn → fork ${SESSION} · pi --session ${SESSION} · run: pi --fork ${SOURCE} --session-id ${SESSION} "/skill:learn here"`,
	);
});

function jsonResponse(status: number, body: unknown): Response {
	return new Response(JSON.stringify(body), {
		status,
		headers: { "content-type": "application/json" },
	});
}

test("registers the fork with the dashboard and keeps its resume line", async () => {
	const calls: { url: string; init: RequestInit }[] = [];
	const fetchImpl = (async (url: string, init: RequestInit) => {
		calls.push({ url, init });
		return jsonResponse(201, { id: `fork-${SESSION}`, resume: `pi --session ${SESSION}` });
	}) as unknown as typeof fetch;

